def join_orders_to_customers(orders_df, customers_df, key="customer_id"):
    dupes = customers_df.groupBy(key).count().filter("count > 1").count()
    if dupes: raise ValueError(f"customers has {dupes} duplicate {key} value(s)")
    return orders_df.join(broadcast(customers_df), key, "left")   # + print rows in, out, unmatched
